const categories=['group','workshop','competition','other'];
const hidden=(h,k,v)=>`<input type="hidden" name="${k}" value="${h(v)}">`;
const date=()=>new Date().toISOString().slice(0,10);
const option=(h,v,l,current)=>`<option value="${h(v)}" ${v===current?'selected':''}>${h(l)}</option>`;
const action=(t,h,btn,row,op,label,extra='')=>btn(t(label),'programAction',`data-module="events" data-op="${op}" data-id="${h(row.id)}" ${extra}`,'secondary');
function eventForm(t,h,r,scope){
  const field=(key,label,value,type='text',attrs='required')=>`<label>${t(label)}<input name="${key}" type="${type}" value="${h(value)}" ${attrs}></label>`;
  return `<form data-form="programs" class="stack">${hidden(h,'module','events')}${hidden(h,'operation',r?'update':'create')}${hidden(h,'scope',scope)}${r?hidden(h,'id',r.id):''}${field('title','programTitle',r?.title||'','text','required maxlength="100"')}<label>${t('programDescription')}<textarea name="description" required maxlength="2000">${h(r?.description||'')}</textarea></label><div class="grid"><label>${t('language')}<select name="language">${['ar','en','sv'].map(l=>option(h,l,t('lang_'+l),r?.language||'en')).join('')}</select></label><label>${t('programCategory')}<select name="eventCategory">${categories.map(c=>option(h,c,t('eventCategory_'+c),r?.eventCategory||'other')).join('')}</select></label></div><div class="grid">${field('start','clubStart',r?.start||date(),'date')}${field('end','clubEnd',r?.end||date(),'date')}${field('registrationEnd','eventRegistrationEnd',r?.registrationEnd||r?.end||date(),'date')}${field('time','programTime',r?.time||'18:00','time')}</div>${field('location','programLocation',r?.location||'','text','required maxlength="160"')}<div class="grid">${field('minimum','programMinimum',r?.minimum||2,'number','required min="1" max="500"')}${field('capacity','programCapacity',r?.capacity||20,'number','required min="1" max="500"')}</div><label>${t('programWaitlist')}<select name="waitlistEnabled">${option(h,'true',t('eventWaitlistEnabled'),r?.waitlistEnabled===false?'false':'true')}${option(h,'false',t('eventWaitlistDisabled'),r?.waitlistEnabled===false?'false':'true')}</select></label><p class="muted">${t('eventFormNote')}</p><button class="primary" type="submit">${t(r?'save':'create')}</button></form>`;
}
function eventCard(t,h,btn,r,admin){
  const status=r.eventStatus||r.status,fill=Math.min(100,Math.round(r.count/r.capacity*100));
  const recorded=(r.attendanceSummary?.present||0)+(r.attendanceSummary?.absent||0)>0;
  const cancelled=!!r.cancelledAt||r.status==='cancelled';
  return `<details class="card stack" data-disclosure-key="event:${h(r.id)}" open><summary><span class="row space wrap"><b>${h(r.title)}</b><span class="badge ${status==='confirmed'?'green':'gold'}">${t('programStatus_'+status)}</span></span></summary><p class="post-text">${h(r.description)}</p><div class="row wrap"><span class="badge">${t('eventCategory_'+r.eventCategory)}</span><span class="badge">${t(r.clubId?'eventClub':'eventPublic')}</span><span class="badge">${h(r.language.toUpperCase())}</span></div><small>${h(r.start)} — ${h(r.end)} · ${h(r.time)} UTC · ${h(r.location)}</small><small>${t('eventRegistrationEnd')}: ${h(r.registrationEnd)}</small><div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${fill}"><span style="width:${fill}%"></span></div><div class="row space wrap"><span>${r.count}/${r.capacity} ${t('programParticipants')} · ${t('programMinimum')}: ${r.minimum}</span><span>${t('programWaitlist')}: ${r.waitCount}</span></div><span class="badge ${r.signupAvailable?'green':'gold'}">${t(r.signupAvailable?'eventSignupAvailable':'eventSignupUnavailable')}</span>${r.joined?`<div class="notice">${cancelled?t('programStatus_cancelled'):r.waiting?t('eventQueuePosition')+': '+r.waitPosition:t('eventSeatReserved')}${!r.waiting&&r.attendanceState!=='unmarked'?' · '+t('eventAttendance_'+r.attendanceState):''}</div>`:''}${!admin&&r.status==='published'?(r.joined&&r.canLeave?action(t,h,btn,r,'leave','leave'):!r.joined&&r.signupAvailable?action(t,h,btn,r,'join',r.count>=r.capacity?'eventJoinWaitlist':'join'):''):''}${r.manage?`<section class="rule stack"><div class="row wrap">${!cancelled&&r.status!=='archived'?`${!recorded||r.status==='published'?r.status==='published'?(recorded?'':action(t,h,btn,r,'draft','programUnpublish')):action(t,h,btn,r,'publish','programPublish'):''}${r.status==='published'&&status!=='ended'?action(t,h,btn,r,'eventRegistration',r.registrationOpen?'eventCloseSignup':'eventOpenSignup',`data-enabled="${!r.registrationOpen}"`)+(recorded?'':action(t,h,btn,r,'eventCancel','eventCancel')):''}`:''}${r.status!=='archived'?action(t,h,btn,r,'archive','programArchive'):''}</div>${!recorded&&!cancelled?`<details data-disclosure-key="event-edit:${h(r.id)}"><summary>${t('wellnessEdit')}</summary>${eventForm(t,h,r,r.clubId?'club':'public')}</details>`:''}<details data-disclosure-key="event-roster:${h(r.id)}"><summary>${t('eventRoster')} · ${r.count+r.waitCount}</summary><div class="grid"><div class="stat-box"><b>${r.attendanceSummary?.present||0}</b><small>${t('eventAttendance_present')}</small></div><div class="stat-box"><b>${r.attendanceSummary?.absent||0}</b><small>${t('eventAttendance_absent')}</small></div><div class="stat-box"><b>${r.attendanceSummary?.unmarked||0}</b><small>${t('eventAttendance_unmarked')}</small></div></div>${(r.roster||[]).map(e=>`<div class="row rule wrap"><span class="grow">${h(e.name)} · ${t(e.waiting?'programWaiting':'eventAttendance_'+e.attendanceState)}</span>${r.canMarkAttendance&&!e.waiting?`<div class="row wrap">${action(t,h,btn,r,'attendance','programAttended',`data-target="${h(e.id)}" data-attended="true"`)}${action(t,h,btn,r,'attendance','programAbsent',`data-target="${h(e.id)}" data-attended="false"`)}</div>`:''}</div>`).join('')||`<p class="empty">${t('noItems')}</p>`}</details></section>`:''}</details>`;
}
export function eventsPage({state,t,h,btn,filter={}}){
  const p=state.programs,scope=p.canAdmin?'public':p.canClubEvents?'club':null;
  const q=String(filter.query||'').toLowerCase().trim();
  const rows=p.items.filter(r=>r.module==='events'&&(!filter.language||r.language===filter.language)&&(!filter.category||r.eventCategory===filter.category)&&(!filter.view||(filter.view==='mine'?r.joined:filter.view==='manage'?r.manage:r.eventStatus===filter.view))&&(!q||[r.title,r.location,r.description].some(v=>String(v||'').toLowerCase().includes(q)))).sort((a,b)=>a.start.localeCompare(b.start)||a.time.localeCompare(b.time));
  const select=(name,label,options,current)=>`<label>${t(label)}<select name="${name}">${option(h,'',t('all'),current||'')}${options.map(([v,l])=>option(h,v,t(l),current)).join('')}</select></label>`;
  return `<div class="stack"><section class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / EVENTS</span><h1>${t('events')}</h1><p>${t('eventIntro')}</p></section><section class="card stack"><p class="notice">${t('programLocalNotice')}</p><form class="stack" data-form="programFilter">${hidden(h,'module','events')}<label>${t('programSearch')}<input type="search" name="query" maxlength="100" value="${h(filter.query||'')}"></label><div class="grid">${select('language','language',['ar','en','sv'].map(l=>[l,'lang_'+l]),filter.language)}${select('category','programCategory',categories.map(c=>[c,'eventCategory_'+c]),filter.category)}${select('view','eventView',[['mine','eventMine'],['manage','eventManaged'],...['pending','confirmed','ended','cancelled','draft','archived'].map(s=>[s,'programStatus_'+s])],filter.view)}</div><button class="secondary" type="submit">${t('programSearch')}</button></form>${scope?`<details><summary>${t('eventCreate')}</summary>${eventForm(t,h,null,scope)}</details>`:''}</section>${rows.map(r=>eventCard(t,h,btn,r,p.canAdmin)).join('')||`<section class="card empty">${t('eventEmpty')}</section>`}</div>`;
}
